pluginManagement {
    repositories {
        gradlePluginPortal()
        google()
        mavenCentral()
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
        maven(url = "https://jitpack.io")
    }
}
// The generator only creates source files for NewPipe's development workflow. Revera vendors
// the generated parser source used by the extractor, so it is not part of this composite build.
include("extractor")
rootProject.name = "NewPipeExtractor"
